// Delegate declaration
public delegate void NotificationHandler(string message);

// Event publisher
public class OrderService {
    public event NotificationHandler OrderPlaced;

    public void PlaceOrder(string product) {
        // Business logic
        OnOrderPlaced($"Order placed: {product}");
    }

    protected virtual void OnOrderPlaced(string message) {
        OrderPlaced?.Invoke(message);
    }
}

// Event subscriber
public class EmailService {
    public EmailService(OrderService orderService) {
        orderService.OrderPlaced += SendEmail;
    }

    private void SendEmail(string message) {
        Console.WriteLine($"Email sent: {message}");
    }
}

// Built-in delegates
Action<string> action = LogMessage;
Func<int, int, int> add = (a, b) => a + b;
Predicate<int> isEven = x => x % 2 == 0;
